SELECT r.id, r.student_id, s.name AS student_name, r.activity_id, a.title AS activity_title, a.start_at AS activity_start_at, a.location AS activity_location, a.policy_type, r.status, r.created_at, r.updated_at FROM registration r JOIN student s ON s.student_id = r.student_id JOIN activity a ON a.id = r.activity_id
r.status = #{status}
AND r.activity_id = #{activityId}
ORDER BY CASE r.status WHEN 'PENDING' THEN 0 WHEN 'APPROVED' THEN 1 WHEN 'REJECTED' THEN 2 WHEN 'CANCELLED' THEN 3 ELSE 4 END, r.created_at DESC, r.id DESC

